"""Render a crawlable, headline-first legal news desk."""
import json,html,datetime
from records_catalog import quick_links
from zoneinfo import ZoneInfo
def collection_stamp(value):
 return datetime.datetime.fromisoformat(value.replace("Z", "+00:00")).astimezone(ZoneInfo("America/Chicago")).strftime("%b %d, %Y at %I:%M %p %Z")
E=html.escape
SECTIONS=[('Texas','Texas courts & legal affairs'),('Fifth Circuit','The Fifth Circuit'),('Practice','The practice of law')]
def build_news_page(root,dist):
 data=json.loads((root/'public/data/news.json').read_text());items=sorted(data['articles'],key=lambda x:x['date'],reverse=True)
 def item(a,lead=False):
  search=E(' '.join(str(a.get(k,'')) for k in ['title','publisher','category','kind']),quote=True)
  return f'<article class="{"lead-story" if lead else "news-item"}" data-news-search="{search}" data-category="{E(a["category"],quote=True)}"><p class="story-meta">{E(a["publisher"])} · <time datetime="{E(a["date"])}">{datetime.date.fromisoformat(a["date"][:10]).strftime("%b %d, %Y")}</time> · {E(a.get("kind","Reporting"))}</p><h{2 if lead else 3}><a href="{E(a["url"],quote=True)}" target="_blank" rel="noopener">{E(a["title"])}</a></h{2 if lead else 3}></article>'
 lead=next((x for x in items if x['category']=='Texas' and x.get('kind')=='Reporting'),items[0] if items else None)
 columns=''.join(f'<section class="news-column" data-column><h2>{E(label)}</h2>'+''.join(item(a) for a in items if a['category']==cat and a!=lead)+'</section>' for cat,label in SECTIONS)
 sources=''.join(f'<li><a href="{E(s["url"],quote=True)}" target="_blank" rel="noopener">{E(s["name"])}</a></li>' for s in data.get('sources',[]))
 failures=[x for x in data.get('feedStatus',[]) if x.get('error')]
 note=f'<p class="refresh-note">{len(failures)} source feeds could not be refreshed at the last attempt. Previously collected links retain their original dates.</p>' if failures else ''
 stamp=collection_stamp(data['checkedAt'])
 content=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Texas & Fifth Circuit Legal News | Courtside Texas</title><meta name="description" content="A daily legal news desk for Texas and the Fifth Circuit. Court decisions, legal developments and practice news, linked to original reporting and official sources."><link rel="canonical" href="https://courtsidetexas.com/news/"><meta name="theme-color" content="#222820"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/news.css"><link rel="stylesheet" href="/search.css"><script src="/news.js" defer></script></head><body><a class="skip" href="#headlines">Skip to headlines</a><div class="news-wrap"><header><nav class="utility" aria-label="Courtside navigation"><a href="/">← Court directory</a><a href="/#local">Local rules</a><a href="/#practice">Practice rules</a><a href="/#desk">My Courts</a><a href="/about/">About Eric</a><a href="/sponsor/">Sponsor</a></nav><div class="edition"><span>TEXAS + THE FIFTH CIRCUIT</span><span>Checked {E(stamp)} · Scheduled twice daily</span></div><a class="brand" href="/"><img src="/brand-mark.svg" alt="Courtside Texas" width="205" height="75"></a><h1>THE LEGAL WIRE</h1><p class="deck">Courts. Cases. Counsel. <span>The links worth opening.</span></p></header><main id="headlines">{quick_links()}<form action="/search/" role="search" class="site-search-form"><label for="news-search" class="visually-hidden">Search all Courtside Texas</label><input id="news-search" name="q" type="search" maxlength="240" placeholder="Search courts, rules, news, and agencies…"><input type="hidden" name="context" value="news"><button type="submit">Search</button></form><p class="site-search-hint">Search all of Courtside. News appears first.</p><div class="news-tools"><label for="news-category">Browse headlines</label><select id="news-category"><option value="all">All sections</option>{''.join(f'<option value="{E(k)}">{E(k)}</option>' for k,_ in SECTIONS)}</select><p id="news-count" aria-live="polite">{len(items)} links</p></div>{note}{item(lead,True) if lead else '<p>No current headlines available. Browse the source links below.</p>'}<p id="no-news" hidden>No headlines match. Try a shorter search or choose another section.</p><div class="news-columns">{columns}</div><section class="source-desk"><h2>Go straight to the source</h2><ul>{sources}</ul></section><details class="editor-note"><summary>About this news desk</summary><p>Current reporting and official court releases, with links to the original source. Headlines are curated or collected from publisher feeds; they are not legal advice or endorsements. Dates are publication dates. Some publishers require subscriptions. The twice-daily feed refresh retains prior links when a source is unavailable; coverage is selective, not exhaustive.</p><p>Court-directory and local-rule updates continue on their separate weekly schedule.</p></details></main><footer><p>A resource by <a href="/about/">Eric A. Hudson</a> · <a href="mailto:ehudson@atlawpllc.com?subject=Courtside%20Texas%20news">Suggest a link</a> · <a href="/sponsor/">Sponsorship inquiries</a></p><a href="/">Courtside Texas →</a><p class="copyright">© {datetime.date.today().year} Eric A. Hudson. Third-party articles and headlines belong to their publishers.</p></footer></div></body></html>'''
 target=dist/'news';target.mkdir(exist_ok=True);(target/'index.html').write_text(content)
